import React,{useRef,useState} from 'react';
export function ProfilerBurstHarness({onTick,heldMint}){const [running,setRunning]=useState(false),[report,setReport]=useState(null),timer=useRef(null);const run=()=>{if(running)return;const base={...(globalThis.__RENDER_COUNTS__||{})};setRunning(true);let i=0;timer.current=setInterval(()=>{i++;const mint=i===250&&heldMint?heldMint:`UnheldMint${i%30}`;onTick?.({mint,priceUsd:i===250?165:Math.random()*10,slot:300000000+i,timestamp:Date.now()});if(i>=500){clearInterval(timer.current);setRunning(false);const d={};for(const[k,v]of Object.entries(globalThis.__RENDER_COUNTS__||{}))d[k]=v-(base[k]||0);setReport({totalTicks:i,deltas:d});console.table(d)}},10)};return <div className="model-note"><span>100Hz Tick Profiler · 500 ticks</span><button type="button" disabled={running} onClick={run}>{running?'Firing…':'Run Stress Burst'}</button>{report&&<b>{report.deltas.ExecutionPanel===0?'ISOLATED':'LEAK DETECTED'}</b>}</div>}
